45	/// 打开 `path` 并以流式方式读取其全部内容，返回完整摘要。
46	///
47	/// 这是 `digest` 与 `check-digest` 共用的唯一文件访问规则：始终以操作
48	/// 系统给出的原始路径打开文件（用于显示的文字绝不参与访问），以原始
49	/// 字节流式计算摘要——空文件、二进制内容与各种换行形式都按同一条规则
50	/// 处理，内存占用与文件大小无关。文件打不开与读取中途失败是两类不同的
51	/// 失败（见 [`FileAccessError`]）；即使已读入一部分内容，读取失败也绝不
52	/// 返回部分摘要。
53	fn digest_file(path: &Path) -> Result<Sha256Digest, FileAccessError> {
54	    let file = File::open(path)
55	        .map_err(|err| FileAccessError::Open(path.to_path_buf(), err))?;
56	    inkseal::digest_reader(file)
57	        .map_err(|err| FileAccessError::Read(path.to_path_buf(), err))
58	}
59	
60	/// 读取单个文件计算完整摘要时的失败，区分“打不开”与“读取中途失败”,
61	/// 以便两条命令共用同一套提示规则。
62	enum FileAccessError {
63	    /// 文件无法打开；携带原始路径与系统给出的原因。
64	    Open(PathBuf, io::Error),
65	    /// 文件已打开但读取中途失败；已读入的部分内容不产生任何摘要。
66	    Read(PathBuf, inkseal::DigestError),
67	}
68	
69	impl FileAccessError {
70	    /// 渲染为既有的单行错误提示（含末尾换行）：仅在此时把路径做损失性
71	    /// 转换并转义控制字符，显示文字不影响也不回溯到实际访问对象。
72	    fn message(&self) -> String {
73	        match self {
74	            FileAccessError::Open(path, err) => {
75	                format!("inkseal: cannot open '{}': {err}\n", path_display(path))
76	            }
77	            FileAccessError::Read(path, err) => {
78	                format!("inkseal: cannot read '{}': {err}\n", path_display(path))
79	            }
80	        }
81	    }
82	}
83	
84	fn run_digest(path: &Path) -> ExitCode {
85	    match digest_file(path) {
86	        Ok(digest) => {
87	            let mut line = digest.to_hex();
88	            line.push('\n');
89	            emit_success(line.as_bytes())
90	        }
91	        Err(err) => emit_error(1, err.message().as_bytes()),
92	    }
93	}
94	
95	/// 把成功结果一次性完整写到标准输出并立即刷出，返回进程退出码。
96	///
97	/// 成功的含义是**整行结果（含末尾换行）已经真正交到输出端**：仅算出
98	/// 摘要或通过比较并不构成成功，写中途失败或最后的刷新失败（例如标准
99	/// 输出被重定向到只读位置，或管道接收方提前关闭）都必须以退出码 1
100	/// 结束，而不是让 `println!` 的 panic 打印崩溃信息，也不能照常报成功。
101	///
102	/// 输出失败时只在标准错误给出一条以 `inkseal:` 开头的单行提示，保留
103	/// 系统给出的具体原因；不补充用法说明，不把摘要改写到标准错误，也不
104	/// 重试整行输出。标准输出此前可能已经收到结果的前几个字节，这些字节
105	/// 无法也不必撤回。若连这条提示都写不出去，同样静默地以退出码 1
106	/// 结束——报告输出失败的过程自身绝不能再崩溃。
107	fn emit_success(line: &[u8]) -> ExitCode {
108	    match write_stdout_all(line) {
109	        Ok(()) => ExitCode::SUCCESS,
110	        Err(err) => {
111	            // 与失败路径同一条规则：提示本身写不出去也忽略，只需保证
112	            // 退出码为 1，绝不经过会因写失败而 panic 的宏。
113	            let hint = format!("inkseal: unable to write to standard output: {err}\n");
114	            let _ = write_stderr_all(hint.as_bytes());
115	            ExitCode::FAILURE
116	        }
117	    }
118	}
119	
120	/// 失败路径的统一出口：把既有的错误提示（原始字节，含其行结构）尽力
121	/// 写到标准错误，然后以约定的退出码（用法错误 `2`、其余失败 `1`）结束。
122	///
123	/// 提示说明的是**已经发生的失败**：接收方是否还读得到提示，不能改变
124	/// 命令对本次操作的判断。标准错误被接到另一个程序而接收方提前关闭管道、
125	/// 或从一开始就拒绝写入时，`eprintln!` 会在 EPIPE/EBADF 上 panic，使
126	/// 进程以崩溃退出码（101）结束并打出崩溃信息，丢掉原本约定的退出码。
127	/// 这里与 [emit_success] 一样直接走 `write` 系统调用并忽略写失败：
128	/// 已经送出的字节保留，写不出去的部分不补齐、不重试、不改写到标准输出，
129	/// 只保证静默地以 `code` 正常结束。
130	fn emit_error(code: u8, message: &[u8]) -> ExitCode {
131	    let _ = write_stderr_all(message);
132	    ExitCode::from(code)
133	}
134	
135	/// 把 `data` 完整写到给定输出端：成功结果与失败提示共用的唯一交付规则。
136	///
137	/// 只要输出端仍可继续接收，临时中断（EINTR）原地重试、一次只接收部分
138	/// 字节（短写）就续写剩余部分，直到全部字节交付完毕——最终内容完整、
139	/// 顺序不变且没有重复。真正的写入错误结束本次交付并返回该错误；对正数
140	/// 计数的 write 返回 0 没有任何进展，按失败处理而不是空转。`target`
141	/// 只用于“毫无进展”这条合成错误的文字，系统给出的真实错误原样返回。
142	#[cfg(unix)]
143	fn write_fd_all(fd: std::os::fd::RawFd, mut data: &[u8], target: &'static str) -> io::Result<()> {
144	    use std::os::raw::c_void;
145	
146	    unsafe extern "C" {
147	        fn write(fd: std::os::fd::RawFd, buf: *const c_void, count: usize) -> isize;
148	    }
149	
150	    while !data.is_empty() {
151	        let written = unsafe { write(fd, data.as_ptr().cast::<c_void>(), data.len()) };
152	        if written < 0 {
153	            let err = io::Error::last_os_error();
154	            // 临时中断不代表任何字节的命运，原地重试。
155	            if err.kind() == io::ErrorKind::Interrupted {
156	                continue;
157	            }
158	            return Err(err);
159	        }
160	        let n = written as usize;
161	        if n == 0 {
162	            // 对正数计数的 write 返回 0 没有可恢复的含义，停止续写，
163	            // 避免在此空转。
164	            return Err(io::Error::new(
165	                io::ErrorKind::WriteZero,
166	                format!("write to {target} returned no progress"),
167	            ));
168	        }
169	        data = &data[n..];
170	    }
171	    Ok(())
172	}
173	
174	/// 非 Unix 目标：标准库句柄不存在上述特殊处理，沿用加锁写入并显式刷新。
175	/// `write_all` 内部已处理短写与 EINTR，语义与 Unix 路径一致。
176	#[cfg(not(unix))]
177	fn write_locked_all(mut handle: impl std::io::Write, data: &[u8]) -> io::Result<()> {
178	    use std::io::Write;
179	
180	    handle.write_all(data)?;
181	    handle.flush()
182	}
183	
184	/// 直接对标准输出的原始文件描述符发起 `write`，绕过标准库 `Stdout`
185	/// 对“输出端不存在/拒绝写入”这类失败的特殊处理——它在某些情况下会把
186	/// 失败（如 fd 以只读方式打开时内核返回的 EBADF）静默报告为成功，导致
187	/// 调用方误以为结果已交付。
188	#[cfg(unix)]
189	fn write_stdout_all(line: &[u8]) -> io::Result<()> {
190	    const STDOUT_FD: std::os::fd::RawFd = 1;
191	    write_fd_all(STDOUT_FD, line, "standard output")
192	}
193	
194	/// 非 Unix 目标：标准库句柄不存在上述特殊处理，沿用加锁写入并显式刷新。
195	#[cfg(not(unix))]
196	fn write_stdout_all(line: &[u8]) -> io::Result<()> {
197	    write_locked_all(io::stdout().lock(), line)
198	}
199	
200	/// 直接对标准错误的原始文件描述符发起 `write`，绕过标准库 `Stderr`
201	/// 的行缓冲以及 `eprintln!`/`writeln!` 在写失败时的 panic（宏内部
202	/// `unwrap`）。任何无法继续写入的错误都返回，由调用方决定忽略——
203	/// 失败提示本身绝不能再崩溃。
204	#[cfg(unix)]
205	fn write_stderr_all(message: &[u8]) -> io::Result<()> {
206	    const STDERR_FD: std::os::fd::RawFd = 2;
207	    write_fd_all(STDERR_FD, message, "standard error")
208	}
209	
210	/// 非 Unix 目标：沿用加锁写入并显式刷新；写失败同样由调用方忽略。
211	#[cfg(not(unix))]
212	fn write_stderr_all(message: &[u8]) -> io::Result<()> {
213	    write_locked_all(io::stderr().lock(), message)
214	}
215	
216	/// 解析用户给出的预期摘要。
217	///
218	/// 解析规则完全来自库（[`Sha256Digest::from_hex_bytes`]），与库的
219	/// `FromStr` 以及摘要的再次显示共用同一套实现：必须恰好是 64 个 ASCII
220	/// 十六进制字符（大小写均可），按其表示的 32 字节摘要值比较，不做任何
221	/// 空白裁剪——前缀、空格、末尾换行、长度不对或含非十六进制字符都视为
222	/// 格式错误；参数无法解码为合法文字时，直接按其原始字节校验，同样视为
223	/// 格式错误。这里只负责把库的类型化错误映射为本命令既有的提示文字。
224	fn parse_expected_digest(arg: &OsStr) -> Result<Sha256Digest, String> {
225	    Sha256Digest::from_hex_bytes(arg.as_encoded_bytes()).map_err(|err| match err {
226	        ParseDigestError::InvalidLength(len) => format!(
227	            "expected digest must be exactly 64 ASCII hexadecimal characters, got {len}"
228	        ),
229	        ParseDigestError::InvalidHexChar(_) => {
230	            "expected digest contains a non-hexadecimal character".to_string()
231	        }
232	    })
233	}
234	
235	fn run_check_digest(path: &Path, expected_arg: &OsStr) -> ExitCode {
236	    // 先校验摘要格式；格式不合法时绝不打开文件——即使路径本身也不存在，
237	    // 仍报告摘要格式问题。
238	    let expected = match parse_expected_digest(expected_arg) {
239	        Ok(digest) => digest,
240	        Err(reason) => {
241	            return emit_error(
242	                2,
243	                format!("inkseal: invalid expected digest: {reason}\n{USAGE}\n").as_bytes(),
244	            );
245	        }
246	    };
247	
248	    // 与 digest 共用同一条文件访问规则；访问失败是文件问题，
249	    // 绝不能被解释成内容不匹配。
250	    let actual = match digest_file(path) {
251	        Ok(digest) => digest,
252	        Err(err) => return emit_error(1, err.message().as_bytes()),
253	    };
254	
255	    if actual == expected {
256	        emit_success(b"OK\n")
257	    } else {
258	        // 内容不匹配：预期与实际都用库的同一显示规则呈现为
259	        // 64 个小写十六进制字符（大小写混用的输入也规范为小写）。
260	        emit_error(
261	            1,
262	            format!(
263	                "inkseal: digest mismatch for '{}'\n\
264	                 expected: {}\n\
265	                 actual:   {}\n",
266	                path_display(path),
267	                expected.to_hex(),
268	                actual.to_hex()
269	            )
270	            .as_bytes(),
271	        )
272	    }
273	}
274	
275	/// 生成可安全输出到标准错误的路径文本：不可解码的字节以替换字符
276	/// （U+FFFD）呈现，控制字符转义为可见写法。该文本只用于显示。
277	fn path_display(path: &Path) -> String {
278	    let lossy = path.to_string_lossy();
279	    if !lossy.contains(char::is_control) {
280	        return lossy.into_owned();
281	    }
282	    let mut out = String::with_capacity(lossy.len());
283	    for ch in lossy.chars() {
284	        match ch {
285	            '\t' => out.push_str("\\t"),
286	            '\n' => out.push_str("\\n"),
287	            '\r' => out.push_str("\\r"),
288	            c if c.is_control() => {
289	                use std::fmt::Write as _;
290	                let _ = write!(out, "\\u{{{:x}}}", c as u32);
291	            }
292	            c => out.push(c),
293	        }
294	    }
295	    out
296	}
