20	    /// 返回 64 个小写十六进制字符，与命令行输出一致（不含换行）。
21	    pub fn to_hex(&self) -> String {
22	        let mut hex = String::with_capacity(64);
23	        for byte in self.0 {
24	            hex.push(char::from_digit((byte >> 4) as u32, 16).unwrap());
25	            hex.push(char::from_digit((byte & 0x0f) as u32, 16).unwrap());
26	        }
27	        hex
28	    }
