289	    fn chunking_strategy_does_not_change_digest() {
290	        let data = long_input();
291	        let expected = digest_reader(&data[..]).unwrap();
292	
293	        // 每次只给少量字节（1 字节），读取器必须被持续读取直到报告结束。
294	        let one_byte = digest_reader(ChunkedReader::new(&data, &[1])).unwrap();
295	        // 每次少量但不等的字节数。
296	        let small_uneven = digest_reader(ChunkedReader::new(&data, &[1, 2, 3, 5, 7])).unwrap();
297	        // 较大片段。
298	        let large = digest_reader(ChunkedReader::new(&data, &[64 * 1024])).unwrap();
299	        // 连续不等长片段，且片段边界与内部缓冲区边界错开。
300	        let uneven = digest_reader(ChunkedReader::new(&data, &[3, 1000, 65537, 17, 4096])).unwrap();
301	
302	        for digest in [one_byte, small_uneven, large, uneven] {
303	            assert_eq!(digest, expected);
304	        }
305	        // 并且结果对应整份原始字节，而非某次读取或前半段。
306	        assert_eq!(expected.to_hex(), LONG_INPUT_HEX);
