456	    fn error_after_partial_read_is_typed_error_not_partial_digest() {
457	        const PREFIX: &[u8] = b"partial bytes before the failure";
458	        struct PartialThenFail {
459	            pos: usize,
460	        }
461	        impl Read for PartialThenFail {
462	            fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
463	                if self.pos < PREFIX.len() {
464	                    let n = (PREFIX.len() - self.pos).min(buf.len());
465	                    buf[..n].copy_from_slice(&PREFIX[self.pos..self.pos + n]);
466	                    self.pos += n;
467	                    Ok(n)
468	                } else {
469	                    Err(io::Error::new(io::ErrorKind::PermissionDenied, "disk vanished"))
470	                }
471	            }
472	        }
