1061	        const O_CLOEXEC: c_int = 0o2000000;
1062	
1063	        let dir = TestDir::new("stderr-partial");
1064	        // 单条错误提示远超 PIPE_BUF（4096）：含约 10000 字节的路径名。
1065	        // 该路径无法打开（ENAMETOOLONG），属于退出码 1 的文件访问失败。
1066	        let path = dir.path().join("A".repeat(10_000));
1067	
1068	        // pipe2(…, O_CLOEXEC) 至关重要：读端不能被子进程继承，否则测试
1069	        // 关闭自己的读端副本后子进程仍持有读端，会无限阻塞地写给自己。
1070	        let mut fds: [RawFd; 2] = [-1, -1];
1071	        assert_eq!(
1072	            unsafe { pipe2(fds.as_mut_ptr(), O_CLOEXEC) },
1073	            0,
1074	            "{}",
1075	            io::Error::last_os_error()
1076	        );
1077	        let set = unsafe { fcntl(fds[1], F_SETPIPE_SZ, 4096) };
1078	        assert!(set >= 0, "shrink pipe: {}", io::Error::last_os_error());
1079	
1080	        let write_end = unsafe { std::fs::File::from_raw_fd(fds[1]) };
1081	        let child = inkseal()
1082	            .args(["digest"])
1083	            .arg(path.as_os_str())
1084	            .stdout(Stdio::piped())
1085	            .stderr(Stdio::from(write_end))
1086	            .spawn()
1087	            .expect("failed to run inkseal");
1088	
1089	        // 子进程的首次写入已填满 4096 字节容量后阻塞；一次性取出这段
1090	        // 连续的提示前缀（在子进程补入更多字节之前读完）。
1091	        let mut prefix = vec![0u8; 4096];
1092	        read_full(fds[0], &mut prefix);
1093	        assert!(
1094	            prefix.starts_with(b"inkseal: cannot open '"),
1095	            "delivered prefix must be the real hint: {:?}",
1096	            String::from_utf8_lossy(&prefix[..40.min(prefix.len())])
1097	        );
1098	
1099	        // 接收方提前关闭：管道中已送达的提示前缀无需也无法补齐，
1100	        // 子进程剩余写入立即失败，但必须仍以退出码 1 正常结束。
1101	        assert_eq!(unsafe { close(fds[0]) }, 0);
1102	
1103	        let output = child.wait_with_output().expect("failed to wait");
1104	        assert_eq!(output.status.code(), Some(1), "{output:?}");
1105	        assert!(output.stdout.is_empty(), "{output:?}");
1106	        assert!(
1107	            !String::from_utf8_lossy(&output.stderr).contains("panicked"),
1108	            "must not crash: {output:?}"
1109	        );
1110	    }
