1112	    /// 阻塞地从 fd 读满 `buf`，EINTR 立即重试。
1113	    #[cfg(target_os = "linux")]
1114	    fn read_full(fd: RawFd, mut buf: &mut [u8]) {
1115	        while !buf.is_empty() {
1116	            let n = unsafe { read(fd, buf.as_mut_ptr().cast::<c_void>(), buf.len()) };
1117	            assert!(n > 0, "read pipe: {}", io::Error::last_os_error());
1118	            let len = n as usize;
1119	            buf = &mut buf[len..];
1120	        }
1121	    }
1122	}
