1124	// ── 临时受阻后完整交付（EINTR 与短写）─────────────────────────────────────────
1125	//
1126	// 接收方仍可继续写入时，对输出端的 write 可能因信号临时中断（EINTR，一个
1127	// 字节都没送出），也可能一次只接收部分字节（短写）。命令必须原地重试中断、
1128	// 续写剩余部分，最终交付的内容与无中断时完全相同：每个字节恰好一次、顺序
1129	// 不变、末尾换行不丢失。这类“临时受阻后恢复”的序列无法从父进程一侧确定
1130	// 性地制造（阻塞写会写满才返回，EINTR 需要子进程安装信号处理器），因此
1131	// 用 LD_PRELOAD 垫片拦截子进程的 write，按脚本逐步注入中断、短写、零进展
1132	// 与不可恢复错误，再核对交付内容与退出状态。
1133	#[cfg(target_os = "linux")]
1134	mod write_retry {
1135	    use super::*;
1136	    use std::sync::OnceLock;
1137	
1138	    /// LD_PRELOAD 垫片源码：拦截子进程对标准输出（fd 1）与标准错误（fd 2）
1139	    /// 的 write 调用，按 INKSEAL_WRITE_SHIM 环境变量给出的逗号分隔脚本
1140	    /// 逐步执行，脚本耗尽后按真实 write 透传。步骤：
1141	    /// `i` = 返回 EINTR（不送出任何字节）；`sN` = 最多写 N 字节的短写；
1142	    /// `z` = 尚有内容待写却返回 0（毫无进展）；`eN` = 返回 errno 为 N 的错误。
1143	    ///
1144	    /// 垫片自身发起写时直接走 write 系统调用，绕开对 write 符号的拦截，
1145	    /// 否则透传分支会递归进入自己。垫片不引入任何 crate 依赖，测试运行时
1146	    /// 用 rustc 编译为 cdylib。
1147	    const SHIM_SOURCE: &str = r#"
1148	use std::os::raw::{c_int, c_void};
1149	use std::sync::atomic::{AtomicUsize, Ordering};
1150	use std::sync::OnceLock;
1151	
1152	#[derive(Clone, Copy)]
1153	enum Step {
1154	    Intr,
1155	    Short(usize),
1156	    Zero,
1157	    Errno(c_int),
1158	}
1159	
1160	fn steps() -> &'static [Step] {
1161	    static STEPS: OnceLock<Vec<Step>> = OnceLock::new();
1162	    STEPS
1163	        .get_or_init(|| {
1164	            std::env::var("INKSEAL_WRITE_SHIM")
1165	                .unwrap_or_default()
1166	                .split(',')
1167	                .filter(|token| !token.is_empty())
1168	                .map(|token| {
1169	                    if token == "i" {
1170	                        Step::Intr
1171	                    } else if token == "z" {
1172	                        Step::Zero
1173	                    } else if let Some(n) = token.strip_prefix('s') {
1174	                        Step::Short(n.parse().expect("short-write length"))
1175	                    } else if let Some(e) = token.strip_prefix('e') {
1176	                        Step::Errno(e.parse().expect("errno"))
1177	                    } else {
1178	                        panic!("unknown shim step: {token}");
1179	                    }
1180	                })
1181	                .collect()
1182	        })
1183	        .as_slice()
1184	}
1185	
1186	static STEP_INDEX: AtomicUsize = AtomicUsize::new(0);
1187	
1188	unsafe extern "C" {
1189	    fn syscall(number: isize, ...) -> isize;
1190	    fn __errno_location() -> *mut c_int;
1191	}
1192	
1193	#[cfg(target_arch = "x86_64")]
1194	const SYS_WRITE: isize = 1;
1195	#[cfg(target_arch = "aarch64")]
1196	const SYS_WRITE: isize = 64;
1197	
1198	const EINTR: c_int = 4;
1199	
1200	fn fail(errno: c_int) -> isize {
1201	    unsafe { *__errno_location() = errno };
1202	    -1
1203	}
1204	
1205	fn real_write(fd: c_int, buf: *const c_void, count: usize) -> isize {
1206	    // 直接发起 write 系统调用：不能调用 libc 的 write，否则会被本垫片
1207	    // 再次拦截而无限递归。
1208	    unsafe { syscall(SYS_WRITE, fd, buf, count) }
1209	}
1210	
1211	#[no_mangle]
1212	pub unsafe extern "C" fn write(fd: c_int, buf: *const c_void, count: usize) -> isize {
1213	    if fd == 1 || fd == 2 {
1214	        let index = STEP_INDEX.fetch_add(1, Ordering::SeqCst);
1215	        match steps().get(index) {
1216	            Some(Step::Intr) => return fail(EINTR),
1217	            Some(Step::Zero) => return 0,
1218	            Some(Step::Errno(errno)) => return fail(*errno),
1219	            Some(Step::Short(limit)) => return real_write(fd, buf, count.min(*limit)),
1220	            None => {}
1221	        }
1222	    }
1223	    real_write(fd, buf, count)
1224	}
1225	"#;
