1230	    /// 每个测试进程只编译一次垫片，产物放在临时目录。
1231	    fn write_shim() -> &'static Path {
1232	        static SHIM: OnceLock<PathBuf> = OnceLock::new();
1233	        SHIM.get_or_init(|| {
1234	            let dir = std::env::temp_dir()
1235	                .join(format!("inkseal-write-shim-{}", std::process::id()));
1236	            fs::create_dir_all(&dir).expect("create shim dir");
1237	            let source = dir.join("write_shim.rs");
1238	            let library = dir.join("libinkseal_write_shim.so");
1239	            fs::write(&source, SHIM_SOURCE).expect("write shim source");
1240	            let rustc = std::env::var_os("RUSTC").unwrap_or_else(|| "rustc".into());
1241	            let status = Command::new(rustc)
1242	                .arg("--edition=2021")
1243	                .arg("--crate-type=cdylib")
1244	                .arg("-O")
1245	                .arg("-o")
1246	                .arg(&library)
1247	                .arg(&source)
1248	                .status()
1249	                .expect("run rustc for write shim");
1250	            assert!(status.success(), "write shim must compile");
