    /// 阻塞地从 fd 读满 `buf`，EINTR 立即重试。
    #[cfg(target_os = "linux")]
    fn read_full(fd: RawFd, mut buf: &mut [u8]) {
        while !buf.is_empty() {
            let n = unsafe { read(fd, buf.as_mut_ptr().cast::<c_void>(), buf.len()) };
            assert!(n > 0, "read pipe: {}", io::Error::last_os_error());
            let len = n as usize;
            buf = &mut buf[len..];
        }
    }
}

